/**
 * Lexicon resolver — maps brand or generic text to ingredient(s), form, class
 * and a plain "commonly used for" gloss. Data comes from data/lexicon.json,
 * generated by scripts/build-lexicon.mjs from data/sources/*.csv with
 * provenance on every row.
 *
 * Matching is deterministic: exact first, then qualifier trimming, then
 * bounded fuzzy matching (edit distance ≤1 for short names, ≤2 for longer,
 * plus a small phonetic-confusion table). A fuzzy match that lands on a
 * look-alike pair is never auto-accepted — it comes back as a question.
 */

import lexiconData from "../../data/lexicon.json";
import type { Resolution, ResolvedIngredient } from "./types";

export interface LexiconIngredient {
  inn: string;
  alt: string[];
  drugClass: string;
  usedFor: string;
  source: string;
  sourceUrl: string;
  license: string;
}

export interface LexiconBrand {
  brand: string;
  ingredients: string[];
  /** Written strength key ("650", "625", "500/125") → per-ingredient strengths. */
  strengths: Record<string, string[]>;
  defaultUnit: string;
  form: string;
  fdc: boolean;
  source: string;
  sourceUrl: string;
  license: string;
}

export interface LexiconErrorProne {
  pattern: string;
  why: string;
  action: string;
  source: string;
  sourceUrl: string;
}

export interface LexiconHighAlert {
  match: string;
  note: string;
  source: string;
  sourceUrl: string;
}

export interface Lexicon {
  ingredients: LexiconIngredient[];
  brands: LexiconBrand[];
  forms: Record<string, string>;
  routes: Record<string, string>;
  lasaPairs: { a: string; b: string; note: string; source: string; sourceUrl: string }[];
  errorProne: LexiconErrorProne[];
  highAlert: LexiconHighAlert[];
}

const data = lexiconData as unknown as Lexicon;

export function getLexicon(): Lexicon {
  return data;
}

function norm(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]/g, "");
}

// Ingredient lookups: INN + alt names, normalised.
const INGREDIENTS_BY_KEY: Map<string, LexiconIngredient> = (() => {
  const m = new Map<string, LexiconIngredient>();
  for (const ing of data.ingredients) {
    m.set(norm(ing.inn), ing);
    for (const alt of ing.alt) m.set(norm(alt), ing);
  }
  return m;
})();

const BRANDS_BY_KEY: Map<string, LexiconBrand> = (() => {
  const m = new Map<string, LexiconBrand>();
  for (const b of data.brands) m.set(norm(b.brand), b);
  return m;
})();

// Phonetic confusions seen in Indian prescriptions and OCR output.
const PHONETIC: [RegExp, string][] = [
  [/ph/g, "f"],
  [/z/g, "s"],
  [/ck/g, "k"],
  [/q/g, "k"],
  [/x/g, "ks"],
  [/ee/g, "i"],
  [/oo/g, "u"],
  [/y/g, "i"],
];

function phonetic(s: string): string {
  let t = norm(s);
  for (const [re, rep] of PHONETIC) t = t.replace(re, rep);
  return t;
}

export function levenshtein(a: string, b: string): number {
  if (a === b) return 0;
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  let cur = new Array<number>(n + 1);
  for (let i = 1; i <= m; i++) {
    cur[0] = i;
    for (let j = 1; j <= n; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    [prev, cur] = [cur, prev];
  }
  return prev[n];
}

function maxEditDistance(name: string): number {
  return name.replace(/[^a-z0-9]/gi, "").length <= 6 ? 1 : 2;
}

/** Fuzzy candidates must share the first character and be at least 4 chars —
 *  OCR slips rarely change a leading letter, and this rule stops words like
 *  "contact" drifting onto brand names. */
function fuzzyAllowed(a: string, b: string): boolean {
  const x = norm(a);
  const y = norm(b);
  if (x.length < 4 || y.length < 4) return false;
  return x[0] === y[0];
}

/** Is this normalised name one half of a look-alike pair? */
function isLasaMember(key: string, pairs: Lexicon["lasaPairs"]): boolean {
  return pairs.some((p) => norm(p.a) === key || norm(p.b) === key);
}

function ingredientResolution(ing: LexiconIngredient, match: Resolution["match"], fuzzyTo?: string): Resolution {
  return {
    kind: "ingredient",
    ingredients: [{ name: ing.inn }],
    fdc: false,
    usedFor: [ing.usedFor],
    drugClasses: [ing.drugClass],
    match,
    fuzzyTo,
  };
}

function brandResolution(
  b: LexiconBrand,
  match: Resolution["match"],
  fuzzyTo?: string,
): Resolution {
  const ingredients: ResolvedIngredient[] = b.ingredients.map((name) => ({ name }));
  const ings = b.ingredients
    .map((n) => INGREDIENTS_BY_KEY.get(norm(n)))
    .filter((x): x is LexiconIngredient => !!x);
  return {
    kind: "brand",
    brand: b.brand,
    ingredients,
    fdc: b.fdc || b.ingredients.length > 1,
    usedFor: ings.map((i) => i.usedFor),
    drugClasses: ings.map((i) => i.drugClass),
    match,
    fuzzyTo,
  };
}

export function unknownResolution(name: string): Resolution {
  void name;
  return {
    kind: "unknown",
    ingredients: [],
    fdc: false,
    usedFor: [],
    drugClasses: [],
    match: "none",
  };
}

/**
 * Resolve a bare medicine-name candidate (form words, strengths and sig
 * already stripped by the tokenizer).
 */
export function resolveName(name: string): Resolution {
  const key = norm(name);
  if (!key) return unknownResolution(name);

  // 1. Exact ingredient.
  const ing = INGREDIENTS_BY_KEY.get(key);
  if (ing) return ingredientResolution(ing, "exact");

  // 2. Exact brand.
  const brand = BRANDS_BY_KEY.get(key);
  if (brand) return brandResolution(brand, "exact");

  // 3. Qualifier trimming: "Ecosprin AV" → "Ecosprin"; "Telma H" → "Telma".
  const pieces = name.trim().split(/[\s-]+/).filter(Boolean);
  for (let take = pieces.length - 1; take >= 1; take--) {
    const prefix = norm(pieces.slice(0, take).join(""));
    const b = BRANDS_BY_KEY.get(prefix);
    if (b) return brandResolution(b, "exact");
    const i = INGREDIENTS_BY_KEY.get(prefix);
    if (i) return ingredientResolution(i, "exact");
  }

  // 4. Fuzzy match with the phonetic table; bounded by name length.
  const dist = maxEditDistance(key);
  const phon = phonetic(key);
  let bestBrand: { b: LexiconBrand; d: number } | null = null;
  let bestIng: { i: LexiconIngredient; d: number } | null = null;
  for (const [k, b] of BRANDS_BY_KEY) {
    if (!fuzzyAllowed(name, b.brand)) continue;
    const d = Math.min(levenshtein(key, k), levenshtein(phon, phonetic(k)));
    if (d <= dist && (!bestBrand || d < bestBrand.d)) bestBrand = { b, d };
  }
  for (const [k, i] of INGREDIENTS_BY_KEY) {
    if (Math.abs(k.length - key.length) > dist || !fuzzyAllowed(name, i.inn)) continue;
    const d = Math.min(levenshtein(key, k), levenshtein(phon, phonetic(k)));
    if (d <= dist && (!bestIng || d < bestIng.d)) bestIng = { i, d };
  }

  const best =
    bestBrand && bestIng
      ? bestBrand.d <= bestIng.d
        ? { kind: "brand" as const, hit: bestBrand }
        : { kind: "ing" as const, hit: bestIng }
      : bestBrand
        ? { kind: "brand" as const, hit: bestBrand }
        : bestIng
          ? { kind: "ing" as const, hit: bestIng }
          : null;

  if (best) {
    const targetKey = best.kind === "brand" ? norm(best.hit.b.brand) : norm(best.hit.i.inn);
    // Never auto-accept a fuzzy match onto a look-alike pair member.
    if (isLasaMember(targetKey, data.lasaPairs)) {
      return unknownResolution(name);
    }
    return best.kind === "brand"
      ? brandResolution(best.hit.b, "fuzzy", best.hit.b.brand)
      : ingredientResolution(best.hit.i, "fuzzy", best.hit.i.inn);
  }

  return unknownResolution(name);
}

/**
 * Attach per-ingredient strengths for a resolved brand, using the strength
 * text as written (e.g. "40", "625", "500/125 mg").
 */
export function enrichStrengths(res: Resolution, strengthAsWritten?: string): Resolution {
  if (!strengthAsWritten || res.kind !== "brand") return res;
  const b = BRANDS_BY_KEY.get(norm(res.brand ?? ""));
  if (!b) return res;
  // Try exact key match first ("625"), then numeric equality ("625 mg").
  const digits = strengthAsWritten.replace(/[^0-9/.]/g, "").trim();
  let perIngredient = b.strengths[digits] ?? b.strengths[strengthAsWritten.trim()];
  if (!perIngredient) {
    // A combination strength like "500/125" may also be written with the
    // total ("625") — accept either direction if the row has both keys.
    const altKeys = Object.keys(b.strengths);
    for (const k of altKeys) {
      if (norm(k) === norm(digits) || k.replace(/[^0-9]/g, "") === digits.replace(/[^0-9/]/g, "")) {
        perIngredient = b.strengths[k];
        break;
      }
    }
  }
  if (!perIngredient) return res;
  const strengths: string[] = perIngredient;
  return {
    ...res,
    ingredients: res.ingredients.map((ing, i) => ({
      ...ing,
      strength: strengths[i] ?? ing.strength,
    })),
  };
}

/** Typeahead over brands and ingredients for the before-list editor. */
export function searchLexicon(
  query: string,
  limit = 8,
): { label: string; ingredients: string[]; kind: "brand" | "ingredient" }[] {
  const q = norm(query);
  if (!q) return [];
  const out: { label: string; ingredients: string[]; kind: "brand" | "ingredient"; score: number }[] = [];
  for (const b of data.brands) {
    const k = norm(b.brand);
    if (k.startsWith(q)) out.push({ label: b.brand, ingredients: b.ingredients, kind: "brand", score: 1 });
    else if (k.includes(q)) out.push({ label: b.brand, ingredients: b.ingredients, kind: "brand", score: 3 });
  }
  for (const ing of data.ingredients) {
    const k = norm(ing.inn);
    if (k.startsWith(q)) out.push({ label: ing.inn, ingredients: [ing.inn], kind: "ingredient", score: 2 });
    else if (ing.alt.some((a) => norm(a).startsWith(q))) {
      out.push({ label: ing.inn, ingredients: [ing.inn], kind: "ingredient", score: 2 });
    }
  }
  out.sort((a, b) => a.score - b.score || a.label.localeCompare(b.label));
  return out.slice(0, limit).map(({ label, ingredients, kind }) => ({ label, ingredients, kind }));
}

/** True when the name (as written) is a known brand or ingredient. */
export function isKnown(name: string): boolean {
  const r = resolveName(name);
  return r.match !== "none";
}
